transfer.sketch:
cands = detect(nodules, scan)                        -- rows: id, z, cx, cy, diam, score
keep  = sortBy(cands, -score)[0:12]                  -- 40 -> 12; ids unchanged by filtering
sheet(keep, views: [window(scan, "lung"), window(scan, "soft")],
      cell: 48 px, zoom: 4).look("top 12 by score")

delivered, warnings = deliver(callPictures, budget)   -- perCall 4, names the rest
byId = { i.id: i for s in deliveredSheets(session) for i in s.items }
for n in answer.nodules:
  if n not in byId: return refuse(E_UNKNOWN_ID, n, valid: keys(byId), hint: "cite ids from the last sheet")
labels = [byId[n] for n in answer.nodules]            -- exact z, cx, cy, diam in mm
